  bh = round(h * 0.2);
  a = blockMedian(0, 0, bw, bh);
  b = blockMedian(w - bw, 0, bw, bh);
  c = blockMedian(0, h - bh, bw, bh);
  d = blockMedian(w - bw, h - bh, bw, bh);
  e = blockMedian(round((w - bw) / 2), round((h - bh) / 2), bw, bh);
